INSERT INTO "notificacoes" (tipo, titulo, descricao, lida, data, createdDate) VALUES (1, 'Bem-vindo(a) às Notificações e Mensagens', 'Agora você recebe **notificações** de erros importantes (ex: falhas ao salvar/carregar do Google Drive) e **mensagens** informativas do app por aqui. Use os ícones de sino e envelope no menu lateral para acessar.', 0, datetime('now'), datetime('now'));
